import * as G from './game.js';
import { esc, portrait } from './ui.js';
import * as S from './sidequests.js';
import { showBargaining, showSecretBroth, showWashing } from './minigames-ui.js';

const $ = query => document.querySelector(query);
const app = $('#app'), dialog = $('#dialog');
const money = G.formatMoney;
const byId = id => G.INGREDIENTS.find(item => item.id === id);
const itemName = id => byId(id)?.shortName || id;
// Icons are tiny; eager loading avoids pop-in while a palette scrolls mid-service.
const icon = id => `<img src="./assets/ingredients/${esc(id)}.svg" alt="" decoding="async">`;
const prefsKey = 'tiem-mi-cay-preferences-v1', recordsKey = 'tiem-mi-cay-records-v2';
let game = G.loadGame(), challenge = null, screen = 'welcome', tab = 'stock', upgradeTab = 'equipment', reviewFilter = 0;
// Keep a save this version cannot read, so starting a new shop never silently destroys it.
if (!game) { try { const raw = localStorage.getItem(G.SAVE_KEY), spare = `${G.SAVE_KEY}-unreadable`; if (raw && !localStorage.getItem(spare)) localStorage.setItem(spare, raw); } catch {} }
let storageWarningShown=false;
let cart = {}, cartDay = null, previousTick = performance.now(), paintElapsed = 0, saveElapsed = 0, toastTimer, audio, returnFocus, holdTimer, holdInterval;
let preferences = { ...G.createGame().settings };
try { const saved = JSON.parse(localStorage.getItem(prefsKey)); for (const key of ['sound','motion']) if (typeof saved?.[key] === 'boolean') preferences[key] = saved[key]; if (['light','dark'].includes(saved?.theme)) preferences.theme = saved.theme; } catch {}
if (game) preferences = game.settings;

function persist() { if (!game || challenge) return; const result = G.saveGame(game); if (!result.ok&&!storageWarningShown) toast(result.message);storageWarningShown=!result.ok; }
function applySettings() { const settings = game?.settings || preferences; document.documentElement.dataset.theme = settings.theme; document.documentElement.classList.toggle('dark', settings.theme === 'dark'); document.documentElement.classList.toggle('reduced-motion', !settings.motion); }
function toast(message) { if (!message) return; clearTimeout(toastTimer); $('#toast').textContent = message; $('#toast').classList.add('show'); toastTimer = setTimeout(() => $('#toast').classList.remove('show'), 3400); }
function sound(ok = true) { if (!(game?.settings || preferences).sound) return; try { audio ||= new AudioContext(); audio.resume(); const osc = audio.createOscillator(), gain = audio.createGain(); osc.connect(gain); gain.connect(audio.destination); osc.frequency.value = ok ? 660 : 190; gain.gain.setValueAtTime(.035, audio.currentTime); gain.gain.exponentialRampToValueAtTime(.0001, audio.currentTime + .1); osc.start(); osc.stop(audio.currentTime + .11); } catch {} }
function focusKey(node = document.activeElement) { return node?.id ? { id: node.id } : node?.dataset.action ? { action: node.dataset.action, item: node.dataset.id || '', index: node.dataset.index || '', delta: node.dataset.delta || '' } : null; }
function restoreFocus(key) { if (!key) return; const target = key.id ? document.getElementById(key.id) : [...document.querySelectorAll('[data-action]')].find(node => node.dataset.action === key.action && (node.dataset.id || '') === key.item && (node.dataset.index || '') === key.index && (node.dataset.delta || '') === key.delta); target?.focus({ preventScroll:true }); }
function replaceContents(node, html) { if (!node || node.innerHTML === html) return; const focused = node.contains(document.activeElement), key = focused ? focusKey() : null; node.innerHTML = html; if (focused) restoreFocus(key); }
// Header and actions stay fixed while only the body scrolls, so buttons never leave the screen.
// Re-rendering the same dialog (rush buying, claiming goals) keeps its scroll position and focus.
function openModal(title, body, actions = '<button class="primary" data-action="close-modal">Đã hiểu</button>', { wide = false } = {}) {
  const same = dialog.open && dialog.querySelector('#dialog-title')?.textContent === title;
  const scroll = same ? dialog.querySelector('.modal-content')?.scrollTop || 0 : 0, key = same && dialog.contains(document.activeElement) ? focusKey() : null;
  if (!dialog.open) returnFocus = focusKey();
  dialog.classList.toggle('modal-wide', wide);
  dialog.innerHTML = `<header class="modal-header"><h2 id="dialog-title">${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Đóng">×</button></header><div class="modal-content">${body}</div><footer class="modal-actions">${actions}</footer>`;
  dialog.querySelector('.modal-content').scrollTop = scroll;
  if (!dialog.open) dialog.showModal(); else if (key) restoreFocus(key); else dialog.querySelector('button')?.focus();
}
function closeModal() { if(dialog.dataset.incident&&game?.activeDay?.pendingIncident){toast('Chọn cách xử lý để tiếp tục ca bán.');return;}dialog.dataset.incident='';dialog.close(); previousTick = performance.now(); restoreFocus(returnFocus); }
function completed(result, { repaint = true, quiet = false } = {}) { if (!quiet || !result.ok) toast(result.message); sound(result.ok); persist(); if (repaint) render(); return result.ok; }
function active() { return !!game?.activeDay; }
function startedItems(kind) { return G.availableIngredients(game).filter(item => item.kind === kind); }
function costs() { return G.dailyOperatingCost(game); }
function clockText(seconds) { const whole = Math.ceil(Math.max(0,seconds)); return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2,'0')}`; }
function decoration(type) { return G.DECORATIONS.find(item => item.id === game?.decoration.selected[type]); }
const decorAssets = { cat:'cat', dog:'dog', hamster:'hamster', cactus:'cactus', leaf:'plant', daisy:'daisy', lantern:'lantern', chime:'chime' };
function decorArt(item) { const asset = decorAssets[item.value]; return asset ? `<img src="./assets/${asset}.svg" alt="${esc(item.name)}">` : `<span class="decor-emoji" role="img" aria-label="${esc(item.name)}">${item.icon}</span>`; }
function decorScene() { return ['pet','plant','lamp'].map(type => { const item = decoration(type); return item ? `<span class="scene-decor scene-${type}" title="${esc(item.name)}">${decorArt(item)}</span>` : ''; }).join(''); }
function shopAsset() { return ({awning_red:'coral',awning_pink:'rose',awning_mint:'green',awning_yellow:'gold',awning_purple:'purple'})[game?.decoration.selected.awning] || 'coral'; }
function applyDecor() { const awning = decoration('awning'); app.style.setProperty('--awning', awning?.value || '#ef4b3f'); app.style.setProperty('--awning-shadow', awning?.shadow || '#c23328'); }
function topbar() { return `<header class="topbar"><div class="top-left"><button class="icon-button" data-action="menu" aria-label="Menu">☰</button><span class="brand-small">🌶️ Tiệm Mì Cay</span><span class="day-label">${challenge?'🏆 Thử thách':`Ngày ${game.day}`}</span>${screen==='play'&&active()?'<span class="top-clock" aria-label="Thời gian còn lại">⏱ <b id="day-clock"></b></span>':''}</div><div class="top-right"><span class="top-rating">★ <b data-value="reputation">${game.reputation.toFixed(1)}</b></span><span class="wallet">🪙 <b data-value="money">${money(game.money)}</b></span><button class="icon-button" data-action="settings" aria-label="Cài đặt">⚙</button></div></header>`; }
function welcome() { app.innerHTML = `<main class="welcome"><div class="welcome-copy"><div class="eyebrow">QUÁN NHỎ • ƯỚC MƠ TO</div><h1>Tiệm<br><em>Mì Cay</em><span class="title-chili">🌶️</span></h1><p class="welcome-subtitle">Một chiếc tiệm nhỏ.<br>Muôn vàn tô mì ấm lòng.</p><div class="welcome-actions">${game ? `<button class="primary" data-action="continue"><span>Tiếp tục tiệm của bạn</span><span>Ngày ${game.day} →</span></button>` : ''}<button class="${game?'secondary':'primary'}" data-action="new-game">${game?'Mở tiệm mới':'Bắt đầu mở tiệm'} <span>→</span></button><div class="welcome-links"><button class="text-button" data-action="help">Cách chơi</button><button class="text-button" data-action="settings">Cài đặt</button><button class="text-button" data-action="import">Nhập bản lưu</button></div></div><p class="local-note">Chơi trên máy của bạn · Tự động lưu tiến trình</p></div><div class="hero-art"><img class="shop-art" src="./assets/shop-coral.svg" alt="Tiệm mì cay nhỏ dưới mái hiên đỏ"><div class="hero-sticker">Nóng hổi<br><strong>vừa thổi vừa ăn!</strong></div></div><footer class="welcome-footer">Bản tái hiện độc lập · Tiệm mì Việt Nam</footer></main>`; }
const tabs = [['stock','▦','Kho'],['prices','₫','Giá bán'],['upgrades','↗','Nâng cấp'],['decor','❀','Trang trí'],['reviews','☆','Đánh giá'],['accounts','▤','Sổ sách']];
function initCart() { if (cartDay !== game.day) { cart = G.suggestedCart(game); cartDay = game.day; } }
function prep() { initCart(); const level = G.levelInfo(game), event = G.dayEvent(game); app.innerHTML = `${topbar()}<main class="prep"><section class="shop-side"><div class="shop-hero"><div class="shop-sign"><span class="sign-label">TIỆM CỦA BẠN</span><h1>${esc(game.name)}</h1><span class="level-label">Cấp ${level.level} · ${esc(level.title)}</span><div class="xp-track"><i style="width:${level.progress*100}%"></i></div><small>${level.nextXp ? `${game.xp} / ${level.nextXp} XP` : `${game.xp} XP · cấp cao nhất`}</small></div><div class="scene-wrap"><div class="prep-illustration"><img src="./assets/shop-${shopAsset()}.svg" alt="Tiệm của bạn">${decorScene()}</div></div></div><div class="daily-card"><div class="daily-head"><h2>Ngày ${game.day}</h2><span class="eyebrow">Sẵn sàng đón khách</span></div><div class="event-note"><span class="event-icon" aria-hidden="true">${event.icon || '📅'}</span><div><strong>${esc(event.name)}</strong><small>${esc(event.description)}</small></div></div><p class="daily-cost">Chi phí mỗi ngày: <strong>${money(costs().total)}</strong> <small>· thuê, điện nước, lương</small></p><div class="daily-actions"><button class="chip-button" data-action="goals">🎯 3 mục tiêu</button><button class="chip-button" data-action="secret" ${game.day<3?'disabled':''}>🍲 Bí truyền${S.secretBroth(game)?' ✓':''}</button><button class="chip-button" data-action="wash" ${!game.lastDay||game.lastDay.day<2||game.lastDay.dineInServed<3||game.lastDay.cash<0?'disabled':''}>🫧 Rửa tô</button></div></div><div class="prep-dock"><span id="cart-summary"></span><button class="primary" id="open-day" data-action="open-day"></button></div></section><section class="management"><nav class="tabs" aria-label="Quản lý tiệm">${tabs.map(([id,symbol,label])=>`<button class="tab ${tab===id?'active':''}" data-action="tab" data-id="${id}" aria-selected="${tab===id}"><span aria-hidden="true">${symbol}</span>${label}</button>`).join('')}</nav><div class="tab-panel" id="panel">${panel()}</div></section></main>`; updateCartQuote(); }
function panel() { return ({stock:stockPanel,prices:pricePanel,upgrades:upgradePanel,decor:decorPanel,reviews:reviewsPanel,accounts:accountsPanel})[tab](); }
function heading(title, description) { return `<div class="panel-heading"><h2>${title}</h2></div><p class="panel-description">${description}</p>`; }
function stockRows(rush = false) { const level = G.levelInfo(game).level; return G.INGREDIENTS.filter(item => game.unlocked.includes(item.id) || item.unlockLevel <= level + (rush?0:1)).map(item => { const unlocked = game.unlocked.includes(item.id), locked = !unlocked && item.unlockLevel > level, qty = (rush ? 0 : cart[item.id]) || 0; return `<div class="stock-row ${locked?'locked':''}"><span class="food-icon">${icon(item.id)}</span><div class="item-info"><strong>${esc(item.name)}</strong><small>${money(unitQuote(item,rush))} / phần · ${item.expiryDays === null ? 'Không hết hạn' : item.expiryDays === 1 ? 'Dùng trong ngày' : `Hạn ${item.expiryDays} ngày`}</small>${!unlocked?`<small class="unlock-note">${locked?`Cấp ${item.unlockLevel}`:`Mở món: ${money(item.unlockPrice)}`}</small>`:''}</div><span class="stock-count" title="Trong kho">${G.inventoryCount(game,item.id)}</span>${rush ? `<button class="small-button" data-action="rush-item" data-id="${item.id}" ${locked?'disabled':''}>+5</button>` : `<div class="quantity-control"><button data-action="quantity" data-id="${item.id}" data-delta="-1" ${locked?'disabled':''} aria-label="Giảm ${esc(item.name)}">−</button><input id="qty-${item.id}" data-quantity="${item.id}" type="number" min="0" max="99" inputmode="numeric" value="${qty}" aria-label="Số lượng ${esc(item.name)}" ${locked?'disabled':''}><button data-action="quantity" data-id="${item.id}" data-delta="1" ${locked?'disabled':''} aria-label="Thêm ${esc(item.name)}">+</button></div>`}</div>`; }).join(''); }
function stockPanel() { return heading('Đi chợ, nhập hàng', 'Chọn số lượng 0–99. Nguyên liệu tươi hết hạn cuối ngày; hàng được dùng theo lô nhập trước.') + `<div class="stock-toolbar"><button class="small-button" data-action="suggest-cart">🧺 Gợi ý nhập hàng</button><button class="small-button" data-action="bargain">Trả giá · −${Math.round(S.marketDiscount(game)*100)}%</button><button class="text-button" data-action="clear-cart">Xóa giỏ</button></div><div class="stock-legend"><span>NGUYÊN LIỆU</span><span>KHO / NHẬP</span></div>${stockRows()}<div class="stock-footer"><button class="secondary" data-action="buy-cart">Chỉ nhập hàng</button><span>Giá mở món được tính một lần trong giỏ.</span></div>`; }
function updateCartQuote() { if (screen !== 'prep') return; const total = G.cartCost(game,cart), count = Object.values(cart).reduce((a,b)=>a+b,0); if ($('#cart-summary')) $('#cart-summary').textContent = count ? `${count} phần · ${money(total)}` : 'Giỏ trống · dùng hàng trong kho'; if ($('#open-day')) { $('#open-day').textContent = count ? `Nhập & mở cửa · ${money(total)} →` : `Mở cửa ngày ${game.day} →`; $('#open-day').disabled = !Number.isFinite(total) || total > game.money; } }
function pricePanel() { return heading('Một tô mì, một mức giá', 'Giá mỗi tô = nước dùng + topping khách chọn. Tăng giá quá cao khiến ít khách ghé và giảm đánh giá.') + startedItems('broth').concat(startedItems('topping')).map(item => `<div class="price-row"><span class="food-icon">${icon(item.id)}</span><div class="item-info"><strong>${esc(item.name)}</strong><small>Giá gốc ${money(item.sellPrice)}</small></div><div class="price-control"><button data-action="price" data-id="${item.id}" data-delta="-1000" aria-label="Giảm giá ${esc(item.name)}">−</button><b>${money(game.prices[item.id])}</b><button data-action="price" data-id="${item.id}" data-delta="1000" aria-label="Tăng giá ${esc(item.name)}">+</button></div></div>`).join(''); }
function upgradePanel() { const level = G.levelInfo(game).level; return heading('Tiệm nhỏ lớn từng ngày', 'Thiết bị mua một lần. Nhân viên nhận lương mỗi ngày làm việc.') + `<div class="subtabs"><button class="${upgradeTab==='equipment'?'active':''}" data-action="upgrade-tab" data-id="equipment">Thiết bị & tiện ích</button><button class="${upgradeTab==='staff'?'active':''}" data-action="upgrade-tab" data-id="staff">Nhân viên</button></div>` + (upgradeTab === 'staff' ? G.STAFF.map((item,index) => `<article class="staff-card"><div class="staff-avatar">${portrait(index+10)}</div><div class="staff-info"><h3>${item.name} <small>· ${item.role}</small></h3><p>${item.description}</p><small>${money(item.wage)} / ngày · Cấp ${item.unlockLevel}</small></div><button class="${game.staff[item.id]?'text-button':'small-button'}" data-action="${game.staff[item.id]?'fire':'hire'}" data-id="${item.id}" ${level<item.unlockLevel?'disabled':''}>${game.staff[item.id]?'Cho nghỉ':level<item.unlockLevel?`Cấp ${item.unlockLevel}`:'Thuê'}</button></article>`).join('') : G.UPGRADES.map(item => `<article class="upgrade-card"><div class="upgrade-art">${item.icon}</div><div class="item-info"><h3>${item.name}</h3><p>${item.description}</p><small>${item.utilities?`Điện nước +${money(item.utilities)}/ngày`:'Không thêm điện nước'} · Cấp ${item.unlockLevel}</small></div><button class="small-button" data-action="upgrade" data-id="${item.id}" ${game.upgrades[item.id]||level<item.unlockLevel||game.money<item.price?'disabled':''}>${game.upgrades[item.id]?'Đã có ✓':level<item.unlockLevel?`Cấp ${item.unlockLevel}`:money(item.price)}</button></article>`).join('')); }
function decorPanel() { const level = G.levelInfo(game).level; return heading('Một góc thật riêng', 'Đổi mái hiên, đặt chậu cây và đón một người bạn nhỏ. Trang trí đã mua có thể đổi lại bất cứ lúc nào.') + `<div class="decor-grid">${G.DECORATIONS.map(item => { const owned = game.decoration.owned.includes(item.id), selected = game.decoration.selected[item.type]===item.id; return `<article class="decor-card ${selected?'selected':''}"><div class="decor-icon" ${item.type==='awning'?`style="background:repeating-linear-gradient(90deg,${item.value} 0 9px,#fff4e6 9px 18px)"`:''}>${item.type==='awning'?'':decorArt(item)}</div><h3>${item.name}</h3><button class="small-button" data-action="decor" data-id="${item.id}" ${selected||level<item.unlockLevel||!owned&&game.money<item.price?'disabled':''}>${selected?'Đang dùng':owned?'Chọn':level<item.unlockLevel?`Cấp ${item.unlockLevel}`:money(item.price)}</button></article>`; }).join('')}</div>`; }
function reviewsPanel() { const reviews = [...game.reviews].reverse().filter(review=>!reviewFilter||review.rating===reviewFilter); return heading('Khách nói gì về tiệm?', `Điểm tiệm ${game.reputation.toFixed(1)} / 5 · Trung bình 30 lượt đánh giá gần nhất.`) + `<div class="review-filters">${[0,5,4,3,2,1].map(value=>`<button class="${reviewFilter===value?'active':''}" data-action="review-filter" data-id="${value}">${value?value+' ★':'Tất cả'}</button>`).join('')}</div>` + (reviews.length ? reviews.map((review,index)=>`<article class="review"><div class="review-avatar">${portrait(index+20)}</div><div class="review-body"><strong>${esc(review.name)}</strong><small>Ngày ${review.day}</small><div class="stars">${'★'.repeat(review.rating)}${'☆'.repeat(5-review.rating)}</div><p>${esc(review.text)}</p>${review.reply?`<p class="owner-reply"><strong>Chủ tiệm:</strong> ${esc(review.reply)}</p>`:''}<button class="text-button" data-action="reply" data-id="${esc(review.id)}">${review.reply?'Sửa trả lời':'Trả lời'}</button></div></article>`).join('') : '<div class="empty-state">☆<h3>Đang chờ câu chuyện đầu tiên</h3><p>Phục vụ một tô mì thật ngon để nhận đánh giá.</p></div>'); }
function accountsPanel() { const c = costs(); return heading('Sổ thu chi của tiệm', 'Nguyên liệu, thiết bị và lương đều được ghi nhận. Tiền cuối ngày có thể âm nếu không đủ trả chi phí.') + `<div class="stat-grid"><div><span>Tổng doanh thu</span><strong>${money(game.stats.revenue)}</strong></div><div><span>Tổng chi phí</span><strong>${money(game.stats.expenses)}</strong></div><div><span>Đã phục vụ</span><strong>${game.stats.served} tô</strong></div><div><span>Tiền tip</span><strong>${money(game.stats.tips)}</strong></div></div><div class="cost-breakdown"><p>Tiền thuê <b>${money(c.rent)}</b></p><p>Điện nước <b>${money(c.utilities)}</b></p><p>Lương nhân viên <b>${money(c.wages)}</b></p><p>Nợ còn lại <b>${money(game.debt)}</b></p></div><div class="account-actions"><button class="secondary" data-action="loan">Vay vốn</button><button class="secondary" data-action="repay" ${!game.debt?'disabled':''}>Trả nợ</button><button class="secondary" data-action="records">🏆 Thành tích</button></div><h3>Những ngày đã qua</h3>${game.history.length?`<div class="table-wrap"><table><thead><tr><th>Ngày</th><th>Tô</th><th>Thu</th><th>Chi</th><th>Lãi/lỗ</th></tr></thead><tbody>${[...game.history].reverse().slice(0,30).map(day=>`<tr><td>${day.day}</td><td>${day.served}</td><td>${money(day.revenue)}</td><td>${money(day.expenses)}</td><td class="${day.profit<0?'negative':'positive'}">${money(day.profit)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="panel-description">Chốt ngày đầu tiên để xem sổ thu chi.</p>'}`; }
// Patience colours move from green to amber to red as a customer waits.
function patience(order) { const ratio = Math.max(0, Math.min(1, order.patience / order.maxPatience)); return { ratio, color: ratio > .5 ? '#8fc86f' : ratio > .25 ? '#f2c14e' : '#ef6a4f' }; }
const seatHTML = '<div class="empty-customer"><svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><ellipse cx="12" cy="7.5" rx="7" ry="2.6" fill="currentColor"/><path d="M6 9 4.5 20M18 9l1.5 11M7.5 15h9" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round"/></svg><small>Bàn trống</small></div>';
function customerHTML() { const orders = game.activeDay.orders.filter(order=>!order.delivery); const count = game.upgrades.table?4:3; return orders.map((order,index)=>{ const {ratio,color} = patience(order); return `<button class="customer ${game.activeDay.selectedOrderId===order.id?'selected':''} ${ratio<.2?'urgent':''}" data-action="order" data-id="${order.id}" aria-label="Đơn của ${esc(order.name)}" aria-pressed="${game.activeDay.selectedOrderId===order.id}"><span class="patience-ring" style="--patience:${ratio*100}%;--ring-color:${color}">${portrait(index)}</span><strong>${esc(order.name)}</strong><small>${order.bowlsTotal>1?`Nhóm · ${order.bowlsServed}/${order.bowlsTotal} tô`:itemName(order.broth)}</small><span class="customer-status">${Math.ceil(order.patience)}s · ${order.spice} 🌶</span></button>`; }).join('') + seatHTML.repeat(Math.max(0,count-orders.length)); }
function deliveryHTML() { return game.activeDay.orders.filter(order=>order.delivery).map(order=>`<button class="delivery-order ${game.activeDay.selectedOrderId===order.id?'selected':''}" data-action="order" data-id="${order.id}"><span class="delivery-summary">🛵 ${esc(order.name)} · ${Math.ceil(order.patience)}s </span><small>Phí app 20%</small></button>`).join(''); }
// The ticket ticks off what the bowl already matches, so phones need no separate checklist.
function ticketHTML() { const order = G.getSelectedOrder(game); if (!order) return '<div class="ticket-empty"><span aria-hidden="true">🍜</span><div><h3>Chờ một chút, khách sắp tới!</h3><p>Có thể luộc mì trước. Nồi cháy khi kim chạy hết vạch.</p></div></div>'; const bowl = game.activeDay.bowl, {ratio} = patience(order), spice = !bowl.started ? '' : bowl.spice === order.spice ? 'done' : bowl.spice > order.spice ? 'over' : ''; return `<div class="ticket-heading"><span>PHIẾU GỌI MÓN${order.delivery?' · GIAO HÀNG':''}</span><strong>${esc(order.name)}</strong></div><div class="ticket-main"><div><h2 class="${bowl.started&&bowl.broth===order.broth?'done':''}">${esc(byId(order.broth)?.name)}</h2><p>${order.bowlsTotal>1?`Tô ${order.bowlsServed+1}/${order.bowlsTotal} · `:''}${money(order.price)}${bowl.started&&bowl.spice?` · tô đang cay ${bowl.spice}`:''}</p></div><span class="spice-stamp ${spice}">CẤP<strong>${order.spice}</strong>🌶</span></div><div class="order-toppings">${order.toppings.length?order.toppings.map(id=>`<span class="${bowl.started&&bowl.toppings.includes(id)?'done':''}">${icon(id)} ${esc(itemName(id))}</span>`).join(''):'<span>Không topping</span>'}</div><div class="ticket-patience ${ratio<.3?'low':''}"><span style="width:${ratio*100}%"></span></div><small class="patience-copy">Khách chờ thêm ${Math.ceil(order.patience)} giây${order.mistakes?` · Đã nhầm ${order.mistakes} lần`:''}</small>`; }
const potArt = '<svg class="pot-art" viewBox="0 0 64 56" aria-hidden="true"><g class="steam"><path d="M22 16c-4-5 4-8 0-13M32 14c-4-5 4-8 0-13M42 16c-4-5 4-8 0-13"/></g><path class="pot-handle" d="M5 30h7M52 30h7"/><path class="pot-body" d="M10 24h44v18a10 10 0 0 1-10 10H20a10 10 0 0 1-10-10Z"/><ellipse class="pot-rim" cx="32" cy="24" rx="23" ry="6"/><ellipse class="pot-water" cx="32" cy="24.5" rx="19" ry="3.8"/><path class="pot-noodles" d="M17 25c3-3 5 2 8 0s5 2 8 0 5 2 8 0 5 2 7 0"/></svg>';
function potsHTML() { const many = game.activeDay.pots.length > 1; return game.activeDay.pots.map((_,index)=>`<button class="pot-button" data-action="pot" data-index="${index}"><span class="pot-icon">${potArt}${many?`<em class="pot-no" aria-hidden="true">${index+1}</em>`:''}</span><strong></strong><small></small><span class="cook-gauge"><i></i><i></i><i></i><b></b></span></button>`).join(''); }
// The bowl is drawn from its real contents: broth colour, noodle doneness, toppings and chili.
const chiliSpots = [[62,50],[98,53],[80,59],[71,46],[92,46],[53,56],[107,50]];
function bowlArt(bowl) {
  const broth = byId(bowl.broth), noodle = {raw:'#f3e7b8',cooked:'#ffd35c',soft:'#eba64a'}[bowl.noodles];
  const noodles = noodle ? `<path d="M36 55c5-8 10 6 16 0s10 6 16 0 10 6 16 0 10 6 16 0 10 6 14 0M42 61c5-6 10 5 15 0s10 5 15 0 10 5 15 0 10 5 15 0" stroke="${noodle}" stroke-width="4.5" fill="none" stroke-linecap="round"/>` : '';
  const chili = chiliSpots.slice(0, bowl.spice).map(([x,y]) => `<ellipse cx="${x}" cy="${y}" rx="3.2" ry="2.1" fill="#d8321f"/>`).join('');
  return `<div class="assembled-bowl ${bowl.broth?'has-broth':''}"><svg viewBox="0 0 160 120" role="img" aria-label="Tô mì đang làm"><ellipse cx="80" cy="113" rx="56" ry="6" fill="#5a2a1a" opacity=".13"/><path d="M13 52c6 38 28 57 67 57s61-19 67-57Z" fill="#e9543f" stroke="#6c2e36" stroke-width="4" stroke-linejoin="round"/><path d="M42 93c20 8 56 8 76 0" stroke="#ff9d85" stroke-width="4" fill="none" stroke-linecap="round"/><ellipse cx="80" cy="52" rx="68" ry="20" fill="#fff2d4" stroke="#6c2e36" stroke-width="4"/><ellipse cx="80" cy="54" rx="57" ry="13.5" fill="${broth?.color || '#ecd6bb'}"/>${broth ? '<ellipse cx="60" cy="50" rx="18" ry="3" fill="#fff" opacity=".22"/>' : ''}${noodles}${chili}</svg><div class="bowl-float-icons">${bowl.toppings.map(id=>`<span>${icon(id)}</span>`).join('')}</div>${bowl.spice?`<span class="bowl-spice">${bowl.spice} 🌶</span>`:''}</div>`;
}
function bowlHTML() { const bowl = game.activeDay.bowl; return `${bowl.started ? bowlArt(bowl) : '<div class="empty-bowl-spot" aria-hidden="true">🥣</div>'}<div class="bowl-meta"><strong>${bowl.broth?esc(itemName(bowl.broth)):bowl.started?'Tô trống':'Chưa lấy tô'}</strong><span>${bowl.noodles?({raw:'Mì còn sống',cooked:'Mì vừa chín ✓',soft:'Mì quá mềm'})[bowl.noodles]:'Chưa có mì'} · ${bowl.toppings.length}/4 topping</span><small>${bowl.started?`Cay ${bowl.spice} · đã dùng ${money(bowl.cost)}`:'Bấm “Lấy tô” để bắt đầu'}</small></div>`; }
// Animated values must not replace buttons between pointer/key down and release.
function setText(node, value) { if (node.textContent !== String(value)) node.textContent = value; }
function updateOrders(container, delivery = false) {
  const orders = game.activeDay.orders.filter(order => !!order.delivery === delivery);
  const existing = new Map([...container.querySelectorAll('[data-id]')].map(node => [node.dataset.id, node]));
  const wanted = new Set(orders.map(order => order.id));
  for (const [id, node] of existing) if (!wanted.has(id)) node.remove();
  orders.forEach((order, index) => {
    let node = existing.get(order.id);
    if (!node) {
      node = document.createElement('button');
      node.className = delivery ? 'delivery-order' : 'customer';
      node.dataset.action = 'order'; node.dataset.id = order.id;
      node.innerHTML = delivery ? '<span class="delivery-summary"></span><small>Phí app 20%</small>' : `<span class="patience-ring">${portrait(index)}</span><strong></strong><small></small><span class="customer-status"></span>`;
    }
    // Do not move a button already in place: moving a focused node can lose focus.
    if (container.children[index] !== node) container.insertBefore(node, container.children[index] || null);
    const selected = game.activeDay.selectedOrderId === order.id;
    node.classList.toggle('selected', selected);
    node.setAttribute('aria-pressed', String(selected));
    node.setAttribute('aria-label', `Đơn của ${order.name}`);
    if (delivery) {
      setText(node.querySelector('.delivery-summary'), `🛵 ${order.name} · ${Math.ceil(order.patience)}s `);
    } else {
      const {ratio, color} = patience(order), ring = node.querySelector('.patience-ring');
      ring.style.setProperty('--patience', `${ratio*100}%`);
      ring.style.setProperty('--ring-color', color);
      node.classList.toggle('urgent', ratio < .2);
      setText(node.querySelector('strong'), order.name);
      setText(node.querySelector('small'), order.bowlsTotal > 1 ? `Nhóm · ${order.bowlsServed}/${order.bowlsTotal} tô` : itemName(order.broth));
      setText(node.querySelector('.customer-status'), `${Math.ceil(order.patience)}s · ${order.spice} 🌶`);
    }
  });
  if (!delivery) {
    const count = Math.max(0, (game.upgrades.table ? 4 : 3) - orders.length);
    const empty = [...container.querySelectorAll('.empty-customer')];
    empty.slice(count).forEach(node => node.remove());
    for (let i = empty.length; i < count; i++) container.insertAdjacentHTML('beforeend', seatHTML);
  }
}
// Stages mirror the engine: raw below 50%, ideal through 78%, then soft until the pot burns.
function potStage(pot) { if (!pot) return ''; const t = pot.elapsed / pot.duration; return t < .5 ? 'raw' : t <= .78 ? 'ideal' : t < .92 ? 'soft' : 'danger'; }
// Short labels keep three pots readable on a 320px phone; the pot number sits on the pot art.
function paintPot(node, pot, index) {
  const stage = potStage(pot), stock = G.inventoryCount(game,'noodles');
  const title = pot ? `Vớt · ${Math.max(0,pot.duration-pot.elapsed).toFixed(1)}s` : 'Luộc mì';
  const status = pot ? ({raw:'Còn sống',ideal:'Vừa chín',soft:'Mì mềm',danger:'Sắp cháy!'})[stage] : stock ? `Còn ${stock} vắt` : 'Hết mì';
  node.classList.toggle('boiling', !!pot);
  for (const name of ['raw','ideal','soft','danger']) node.classList.toggle(`stage-${name}`, stage === name);
  setText(node.querySelector('strong'), title);
  setText(node.querySelector('small'), status);
  const label = `Nồi ${index+1}: ${pot ? 'vớt mì' : 'luộc mì'}, ${status}`;
  if (node.getAttribute('aria-label') !== label) node.setAttribute('aria-label', label);
  node.querySelector('.cook-gauge b').style.left = `${pot ? Math.min(100,pot.elapsed/pot.duration*100) : 0}%`;
}
function updatePots() {
  const pots = game.activeDay.pots;
  $('#pots').style.setProperty('--pot-count', pots.length);
  $('#pots').querySelectorAll('.pot-button').forEach((node,index) => paintPot(node,pots[index],index));
  $('.play').classList.toggle('has-hot-pots', pots.some(Boolean));
}
function ingredientButton(item) { return `<button class="ingredient-button ${item.kind}-button" data-action="${item.kind}" data-id="${item.id}"><span class="food-icon">${icon(item.id)}</span><strong>${esc(item.shortName)}</strong><small data-stock="${item.id}"></small></button>`; }
// Three groups: front of house, cooking station and pantry. CSS arranges them as
// one column (phones), two columns (short landscape) or three columns (wide screens).
function play() { const day = game.activeDay; if (!day) { screen='prep'; prep(); return; } app.innerHTML = `${topbar()}<main class="play"><section class="front" aria-label="Khách và phiếu gọi món"><div class="street"><div class="awning" aria-hidden="true"></div><div class="street-title"><h1>${esc(game.name)}</h1></div><div class="customer-lane" id="customers">${customerHTML()}</div><div class="delivery-strip" id="deliveries">${deliveryHTML()}</div><div class="street-counter"><span>Đã bán <b id="served-count">${day.served}</b> tô</span><span>Combo <b id="combo-count">${day.combo}</b> 🔥</span><span id="day-revenue">${money(day.revenue)}</span></div><div class="day-progress"><i id="day-progress-bar"></i></div>${decorScene()}</div><div class="day-event">${esc(day.event.name)} · ${esc(day.event.description)}</div><div id="closing-notice" class="closing-notice"></div><div class="order-ticket" id="ticket">${ticketHTML()}</div><div class="service-actions"><button class="tool" data-action="rush"><span aria-hidden="true">🧺</span>Nhập gấp</button><button class="tool" data-action="stockout"><span aria-hidden="true">🚫</span>Hết món</button><button class="tool" data-action="goals"><span aria-hidden="true">🎯</span>Mục tiêu</button><button class="tool" data-action="help"><span aria-hidden="true">❔</span>Cách nấu</button><button class="tool" data-action="finish"><span aria-hidden="true">🏁</span>Chốt ngày</button></div></section><section class="station" aria-label="Bếp"><div class="kitchen-heading"><h2>Góc bếp nhỏ</h2></div><div class="station-title pots-title"><span>02</span>LUỘC & VỚT MÌ<small>Vớt ở vùng xanh · 50–78%</small><small id="noodle-stock"></small></div><div class="cooking-row" id="pots">${potsHTML()}</div><div class="bench"><div class="worktop" id="bowl-display">${bowlHTML()}</div><button class="basket-button" data-action="basket" id="basket-button" title="Rổ mì chín của Bé Na" ${!game.staff.chef?'hidden':''}><span aria-hidden="true">🧺</span> <span class="basket-label">Lấy mì</span> (<b id="basket-count">0</b>)</button></div><div class="seasoning"><strong>🌶 Thêm ớt</strong><small>Mỗi lần +1 cấp · không thể giảm</small></div><div class="serve-row"><button class="discard" data-action="discard">Bỏ tô</button><button class="chili-button" data-action="chili" aria-label="Thêm ớt">🌶 +1 <b id="chili-level">0 / 7</b></button><button class="primary serve" data-action="serve">Giao món <span>→</span></button></div></section><section class="pantry" aria-label="Nguyên liệu"><div class="station-title"><span>01</span>TÔ & NƯỚC DÙNG</div><div class="broth-row"><button class="ingredient-button new-bowl" id="take-bowl" data-action="bowl"><span class="food-icon">${icon('bowls')}</span><strong>Lấy tô</strong><small data-stock="bowls"></small></button>${startedItems('broth').map(ingredientButton).join('')}</div><div class="station-title"><span>03</span>TOPPING</div><div class="topping-row">${startedItems('topping').map(ingredientButton).join('')}</div></section></main>`; updatePlay(); }
function updatePlay() { if (screen !== 'play' || !game?.activeDay) return; const day = game.activeDay, bowl = day.bowl; $('[data-value="money"]').textContent=money(game.money); $('[data-value="reputation"]').textContent=game.reputation.toFixed(1); updateOrders($('#customers')); updateOrders($('#deliveries'),true); replaceContents($('#ticket'),ticketHTML()); updatePots(); replaceContents($('#bowl-display'),bowlHTML()); $('#served-count').textContent=day.served; $('#combo-count').textContent=day.combo; $('#day-revenue').textContent=money(day.revenue); setText($('#day-clock'),game.phase==='closing'?`Dọn ${clockText(day.closingRemaining)}`:clockText(day.remaining)); $('#day-progress-bar').style.width=`${(1-day.remaining/210)*100}%`; $('#closing-notice').textContent=game.phase==='closing'?`Đã ngừng nhận khách. Còn ${Math.ceil(day.closingRemaining)} giây hoàn thành đơn.`:''; $('#closing-notice').hidden=game.phase!=='closing'; $('#chili-level').textContent=`${bowl.spice} / 7`; setText($('#noodle-stock'),`Kho mì ${G.inventoryCount(game,'noodles')} · hao phí ${money(day.waste)}`); setText($('#basket-count'),day.readyNoodles.length); $('#basket-button').disabled=!day.readyNoodles.length||!bowl.started||!!bowl.noodles;
  document.querySelectorAll('[data-stock]').forEach(node=>node.textContent=`Còn ${G.inventoryCount(game,node.dataset.stock)}`);
  document.querySelectorAll('[data-action="broth"]').forEach(node=>node.disabled=!bowl.started||!!bowl.broth||!G.inventoryCount(game,node.dataset.id));
  document.querySelectorAll('[data-action="topping"]').forEach(node=>node.disabled=!bowl.started||bowl.toppings.includes(node.dataset.id)||bowl.toppings.length>=4||!G.inventoryCount(game,node.dataset.id));
  $('#take-bowl').disabled=bowl.started||!G.inventoryCount(game,'bowls'); $('[data-action="chili"]').disabled=!bowl.started||bowl.spice>=7; $('[data-action="discard"]').disabled=!bowl.started; $('[data-action="serve"]').disabled=!bowl.started||!bowl.noodles||!bowl.broth;
}
function render() { const key=app.contains(document.activeElement)?focusKey():null; applySettings(); applyDecor(); if (screen==='welcome'||!game) welcome(); else if (screen==='prep') prep(); else play(); restoreFocus(key); if(screen==='play')showIncident(); }
function showIncident() {
  const incident=game?.activeDay?.pendingIncident;if(!incident||dialog.dataset.incident===incident.id&&dialog.open)return;
  const description=incident.type==='dash'?`${incident.name} vội rời quán khi chưa trả ${money(incident.bill)}.`:incident.type==='money'?`${incident.name} ${incident.overpaid?'đưa thừa':'trả thiếu'} ${money(incident.amount)}.`:incident.type==='debt'?`${incident.name} xin ghi nợ ${money(incident.bill)} và hẹn quay lại.`:`${incident.name} phàn nàn có sợi tóc trong tô mì. Bạn xử lý thế nào?`;
  const note=incident.type==='dash'?'Tự đuổi theo có 65% cơ hội thu tiền, nhưng khách khác chờ thêm 6 giây. Nhờ nhân viên có 85% cơ hội và bếp chậm 12 giây.':incident.type==='money'?'Thái độ của chủ tiệm ảnh hưởng đánh giá và thiện cảm của khách.':incident.type==='debt'?'Khoản ghi nợ được theo dõi riêng; khách có thể trả khi sang ngày mới.':'Hoàn tiền mất cả hóa đơn. Làm phần mới tốn 10.000đ. Giải thích có thể khiến khách không hài lòng.';
  openModal('Một chuyện nhỏ ở tiệm',`<div class="incident-art">${({dash:'🏃',money:'💵',debt:'📝',hair:'🥣'})[incident.type]}</div><p>${esc(description)}</p><p class="muted">${note}</p>`,incident.options.map(option=>`<button class="secondary" data-action="incident" data-id="${esc(option.id)}">${esc(option.label)}</button>`).join(''));
  dialog.dataset.incident=incident.id;dialog.querySelector('.modal-close').hidden=true;dialog.querySelector('.modal-actions button')?.focus();
}
function miniContext() { return {game,dialog,openModal,persist,render,toast,ingredients:G.INGREDIENTS}; }
function unitQuote(item,rush=false) { const quote=G.cartCost(game,{[item.id]:1},{rush}),unlock=game.unlocked.includes(item.id)?0:item.unlockPrice;return Number.isFinite(quote)?quote-unlock:item.price; }
function newGameModal() { openModal('Tiệm nhỏ của bạn',`<p>Bạn có ${money(400000)} vốn và một gian bếp trống. Chọn tên tiệm rồi đi chợ nào!</p><label class="field-label" for="shop-name">Tên tiệm</label><input id="shop-name" maxlength="40" value="Tiệm Mì Cay" autocomplete="off">${game?'<p class="warning">Bắt đầu tiệm mới sẽ thay bản lưu hiện tại. Bạn có thể xuất bản lưu trước ở menu.</p>':''}`,'<button class="secondary" data-action="close-modal">Quay lại</button><button class="primary" data-action="create">Mở tiệm của tôi →</button>'); $('#shop-name').select(); }
function settingsModal() { const settings=game?.settings||preferences; openModal('Một chút tùy chỉnh',`<div class="settings-list"><label>Âm thanh <input type="checkbox" data-setting="sound" ${settings.sound?'checked':''}></label><label>Chuyển động <input type="checkbox" data-setting="motion" ${settings.motion?'checked':''}></label><label>Giao diện tối <input type="checkbox" data-setting="dark" ${settings.theme==='dark'?'checked':''}></label></div><p class="muted">Tiệm tạm dừng khi bạn mở cửa sổ này.</p>`); }
const helpPages = [
 ['Mở tiệm đầu tiên','Bạn bắt đầu với 400.000đ và kho trống. Chọn số lượng hoặc “Gợi ý nhập hàng”, rồi nhập hàng và mở cửa. Nước dùng và bò cần dùng trong ngày. Mì giữ 5 ngày, tô không hết hạn.'],
 ['Nấu một tô mì','Đọc phiếu: nước dùng, topping và cấp cay. Lấy tô, chọn nước dùng rồi luộc mì. Có thể luộc trước khi lấy tô. Vớt trong vùng xanh (50–78%); vớt sớm còn sống, muộn sẽ mềm, hết vạch sẽ cháy.'],
 ['Thêm đúng, giao đúng','Mỗi lần thêm ớt tăng 1 cấp, tối đa 7. Topping tối đa 4 loại. Nguyên liệu trừ ngay khi dùng và không lấy ra được. Nếu nhầm, bỏ tô sẽ mất nguyên liệu. Món đúng sẽ giao cho khách đang chờ phù hợp.'],
 ['Khách, nhóm và giờ đóng cửa','Nhóm khách có thể gọi nhiều tô khác nhau. Giao sai làm khách mất kiên nhẫn; mì sống hoặc mềm vẫn giao được nhưng bị chê. Một ngày bán 210 giây và thêm tối đa 60 giây dọn đơn; giờ cuối không nhận khách mới.'],
 ['Phát triển bền vững','Tô đúng được XP và tiền tip; hoàn thành mục tiêu có thêm thưởng. Mở món mới, nâng cấp bếp và thuê người qua từng cấp. Giá cao ảnh hưởng lượng khách. Cuối ngày trả đủ tiền thuê, điện nước, lương và hao hụt. Vay vốn trong Sổ sách nếu cần.']
];
let helpStep = 0;
const helpArt = ['shop-coral','bowl','mascot','cat','plant'];
function helpModal() { const [title,text]=helpPages[helpStep]; openModal(title,`<div class="help-illustration"><img src="./assets/${helpArt[helpStep]}.svg" alt=""></div><p>${text}</p><p class="muted">${helpStep+1} / ${helpPages.length}</p>`,`<button class="secondary" data-action="help-prev" ${helpStep===0?'disabled':''}>Trước</button><button class="primary" data-action="${helpStep===helpPages.length-1?'close-modal':'help-next'}">${helpStep===helpPages.length-1?'Vào bếp thôi':'Tiếp →'}</button>`); }
function goalsModal() { openModal('Ba niềm vui hôm nay',game.goals.map(goal=>`<article class="goal-card"><h3>${esc(goal.name)}</h3><p>${esc(goal.description)}</p><progress value="${goal.progress}" max="${goal.target}"></progress><small>${goal.progress}/${goal.target} · ${money(goal.rewardMoney)} + ${goal.rewardXp} XP</small><button class="small-button" data-action="claim" data-id="${goal.id}" ${goal.claimed||goal.progress<goal.target?'disabled':''}>${goal.claimed?'Đã nhận ✓':'Nhận thưởng'}</button></article>`).join('')+'<p class="muted">Mục tiêu hoàn thành sẽ tự nhận thưởng khi chốt ngày.</p>'); }
function rushModal() { openModal('Chuyến chợ khẩn cấp', '<p>Nhập thêm từng 5 phần với giá bằng 150% giá thường. Tiệm tạm dừng trong lúc chọn.</p><div class="rush-list">'+stockRows(true)+'</div>', undefined, { wide:true }); }
function summaryModal(summary) { openModal(`Một ngày ${summary.profit>=0?'ấm lòng':'nhiều bài học'}`,`<div class="summary-hero">${summary.profit>=0?'🌅':'🌧️'}<h3>Ngày ${summary.day} đã khép lại</h3><p>${summary.served} tô mì · ${summary.lost} khách bỏ về</p></div><div class="cost-breakdown"><p>Doanh thu (gồm tip) <b>${money(summary.revenue)}</b></p><p>Thưởng mục tiêu <b>${money(summary.goalRewards)}</b></p><p>Nhập hàng & vận hành <b>−${money(summary.expenses)}</b></p><p>Lãi / lỗ <b class="${summary.profit<0?'negative':'positive'}">${money(summary.profit)}</b></p><p>Hao phí & hết hạn <b>${money(summary.waste)}</b></p><p>Trả gốc khoản vay <b>${money(summary.principalPaid)}</b></p></div><p class="muted">Hao phí đã nằm trong tiền nhập nguyên liệu${summary.interestPaid?`; lãi vay ${money(summary.interestPaid)} đã tính trong chi phí vận hành`:''}, không bị tính hai lần.</p><p>Tiền trong ví: <strong>${money(game.money)}</strong> · Nợ: ${money(game.debt)}</p>`,'<button class="primary" data-action="close-modal">Chuẩn bị ngày mới →</button>'); }
function handleEnd(result) { if (!result.finished) { persist(); updatePlay(); if (result.message) toast(result.message); return; } if (challenge) { completeChallenge(result.summary); return; } cartDay=null; screen='prep'; persist(); render(); summaryModal(result.summary); }
function menuModal() { openModal('Góc của chủ tiệm',`<div class="menu-list"><button class="secondary" data-action="rename">Đổi tên tiệm</button><button class="secondary" data-action="export">Xuất bản lưu</button><button class="secondary" data-action="import">Nhập bản lưu</button><button class="secondary" data-action="records">🏆 Thành tích & thử thách</button><button class="secondary" data-action="home">Về màn hình đầu</button></div><p class="muted">Đã tự lưu trên trình duyệt này. Xuất bản lưu để giữ một bản riêng.</p>`); }
function loanModal() { openModal('Vay vốn mở tiệm',`<p>Vay tối đa hai lần để giúp tiệm vượt lúc khó khăn. Lãi cố định 10%, trả dần trong 6 lần chốt ngày có tiền.</p><p>Đang nợ: <strong>${money(game.debt)}</strong> · Đã vay ${game.loansTaken}/2 lần.</p><p>Số tiền vay được tính theo khoản thiếu và quy mô hiện tại của tiệm.</p>`,'<button class="secondary" data-action="close-modal">Quay lại</button><button class="primary" data-action="take-loan">Nhận khoản vay</button>'); }
function readRecords() { try { const rows=JSON.parse(localStorage.getItem(recordsKey)); return Array.isArray(rows)?rows.filter(row=>row&&/^\d{4}-\d{2}-\d{2}$/.test(row.date)&&Number.isFinite(row.score)&&Number.isSafeInteger(row.served)&&typeof row.name==='string').slice(-30):[]; } catch { return []; } }
function recordsModal() { const rows=readRecords().sort((a,b)=>b.score-a.score); openModal('Bảng thành tích của bạn',`<p>${game.stats.served} tô đã bán · ${game.stats.perfect} lượt 5 sao · Ngày cao nhất ${money(game.stats.bestDay)}</p><h3>Thử thách mỗi ngày</h3><p>Cùng một vốn, nguyên liệu và chuỗi khách cho ngày hôm nay. Chơi một ca riêng; tiệm chính giữ nguyên. Kết quả được lưu trên máy này.</p>${rows.length?`<ol class="records-list">${rows.map(row=>`<li><strong>${esc(row.name.slice(0,40))}</strong><span>${row.score} điểm · ${row.served} tô · ${row.date}</span></li>`).join('')}</ol>`:'<p class="muted">Chưa có kỷ lục thử thách.</p>'}<p class="muted">Đây là bảng cá nhân trên máy, không kết nối giải đấu hay người chơi trực tuyến.</p>`,`<button class="secondary" data-action="close-modal">Quay lại</button><button class="primary" data-action="challenge" ${active()||challenge?'disabled':''}>Chơi ca thử thách →</button>`, { wide:true }); }
function startChallenge() { if (active()||challenge) return; persist(); const date=new Date().toISOString().slice(0,10); const seed=Number(date.replaceAll('-','')), stream=start=>{let value=start>>>0;return()=>{value=(value*1664525+1013904223)>>>0;return value/4294967296;};};
  // Separate streams: how a player serves must not change which customers arrive next.
  challenge={base:game,date,random:stream(seed),serveRandom:stream(seed^0x9e3779b9)}; game=G.createGame(game.name); game.settings={...challenge.base.settings}; game.money=1000000; G.buyCart(game,{bowls:60,noodles:60,kimchi:60,beef:30,sausage:30}); G.beginDay(game); closeModal(); screen='play'; render(); toast('Ca thử thách bắt đầu. Tiệm chính đã được giữ lại.'); }
function completeChallenge(summary) { const score=Math.max(0,summary.served*100+(summary.perfect||0)*50-summary.mistakes*30); const record={date:challenge.date,name:challenge.base.name,score:Math.max(0,score),served:summary.served}; try { localStorage.setItem(recordsKey,JSON.stringify([...readRecords(),record].slice(-30))); } catch { toast('Không thể lưu kỷ lục.'); } game=challenge.base; challenge=null; cartDay=null; screen='prep'; persist(); render(); openModal('Ca thử thách hoàn thành',`<div class="summary-hero">🏆<h3>${record.score} điểm</h3><p>${record.served} tô · ${summary.mistakes} lần nhầm</p></div><p>Tiệm chính đã sẵn sàng với nguyên trạng trước thử thách.</p>`); }
function exportSave() { if (!game) return; const blob=new Blob([JSON.stringify(challenge?.base||game,null,2)],{type:'application/json'}), url=URL.createObjectURL(blob), a=document.createElement('a'); a.href=url;a.download=`tiem-mi-cay-ngay-${(challenge?.base||game).day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); toast('Đã xuất bản lưu.'); }
function importSave() { const input=document.createElement('input'); input.type='file';input.accept='.json,application/json'; input.onchange=async()=>{const file=input.files[0]; if (!file)return; if(file.size>2000000){toast('Bản lưu quá lớn.');return;} const raw=await file.text(), loaded=G.loadGame({getItem:()=>raw}); if(!loaded){toast('Bản lưu không hợp lệ hoặc đã hỏng.');return;} openModal('Nhập tiệm đã lưu',`<p>Thay bản lưu hiện tại bằng tiệm <strong>${esc(loaded.name)}</strong>, ngày ${loaded.day}?</p>`,'<button class="secondary" data-action="close-modal">Hủy</button><button class="primary" id="confirm-import">Nhập bản lưu</button>'); $('#confirm-import').onclick=()=>{game=loaded;challenge=null;cartDay=null;screen=active()?'play':'prep';closeModal();persist();render();toast('Đã nhập bản lưu.');};};input.click(); }
function adjustQuantity(id,delta) { cart[id]=Math.min(99,Math.max(0,(cart[id]||0)+delta)); const input=document.getElementById(`qty-${id}`);if(input)input.value=cart[id];updateCartQuote(); }
function stopHold() { clearTimeout(holdTimer);clearInterval(holdInterval); }
// Remember intent without activating on down: dragging away still cancels natively.
// A pot may burn or be collected by the chef before the player's release.
let potPresses = new WeakMap();
function rememberPotPress(event) {
  const button = event.target.closest('[data-action="pot"]');
  if (event.type === 'keydown') {
    if (!['Space','Enter'].includes(event.code)) return;
    if (event.repeat) { if (button && event.code === 'Enter') event.preventDefault(); return; }
  }
  if (button && !button.disabled && active()) potPresses.set(button, {day:game.activeDay, pot:game.activeDay.pots[Number(button.dataset.index)]});
}
document.addEventListener('pointerdown', rememberPotPress);
document.addEventListener('keydown', rememberPotPress);
document.addEventListener('pointercancel', event => { const button = event.target.closest('[data-action="pot"]'); if (button) potPresses.delete(button); });
window.addEventListener('blur', () => { potPresses = new WeakMap(); });
document.addEventListener('pointerdown',event=>{const button=event.target.closest('[data-action="quantity"]');if(!button||button.disabled)return;stopHold();holdTimer=setTimeout(()=>{holdInterval=setInterval(()=>adjustQuantity(button.dataset.id,Number(button.dataset.delta)),85);},400);});
for (const type of ['pointerup','pointercancel','blur']) window.addEventListener(type,stopHold);
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.quantity){const value=Math.min(99,Math.max(0,Math.trunc(Number(input.value)||0)));cart[input.dataset.quantity]=value;if(input.value!==''&&Number(input.value)!==value)input.value=value;updateCartQuote();}});
document.addEventListener('change',event=>{const key=event.target.dataset.setting;if(!key)return;const settings=game?.settings||preferences;if(key==='dark')settings.theme=event.target.checked?'dark':'light';else settings[key]=event.target.checked;preferences={...settings};try{localStorage.setItem(prefsKey,JSON.stringify(preferences));}catch{}if(challenge)challenge.base.settings={...settings};persist();applySettings();});
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  const {action,id}=button.dataset;
  if (action === 'pot') {
    const press = potPresses.get(button); potPresses.delete(button);
    if (press && (press.day !== game?.activeDay || press.pot !== game.activeDay.pots[Number(button.dataset.index)])) {
      toast('Nồi đã thay đổi trong lúc nhấn. Chọn lại thao tác nhé.'); updatePlay(); return;
    }
  }
  if(action==='close-modal'){closeModal();return;} if(action==='new-game'){newGameModal();return;} if(action==='settings'){settingsModal();return;} if(action==='help'){helpStep=0;helpModal();return;} if(action==='help-next'){helpStep++;helpModal();return;} if(action==='help-prev'){helpStep--;helpModal();return;} if(action==='import'){importSave();return;}
  if(action==='create'){game=G.createGame($('#shop-name').value);game.settings={...preferences};challenge=null;cartDay=null;screen='prep';closeModal();persist();render();return;}
  if(!game)return;
  if(action==='continue'){screen=active()?'play':'prep';previousTick=performance.now();render();return;}
  if(action==='menu'){menuModal();return;} if(action==='home'){closeModal();screen='welcome';persist();render();return;} if(action==='export'){exportSave();return;} if(action==='rename'){openModal('Tên tiệm của bạn','<label for="rename-input">Tên mới</label><input id="rename-input" maxlength="40" value="'+esc(game.name)+'">','<button class="primary" data-action="save-name">Lưu tên</button>');return;} if(action==='save-name'){game.name=$('#rename-input').value.trim().slice(0,40)||'Tiệm Mì Cay';closeModal();persist();render();return;}
  if(action==='tab'){tab=id;render();return;} if(action==='upgrade-tab'){upgradeTab=id;render();return;} if(action==='quantity'){adjustQuantity(id,Number(button.dataset.delta));return;} if(action==='suggest-cart'){cart=G.suggestedCart(game);render();return;} if(action==='clear-cart'){cart={};render();return;}
  if(action==='buy-cart'||action==='open-day'){if(Object.values(cart).some(Boolean)){const result=G.buyCart(game,cart);if(!result.ok){completed(result);return;}cart={};persist();}else if(action==='buy-cart'){toast('Chọn nguyên liệu cần nhập.');return;}if(action==='open-day'){const result=G.beginDay(game);if(result.ok)screen='play';completed(result);}else{render();toast('Đã nhập hàng vào kho.');}return;}
  if(action==='price'){completed(G.setPrice(game,id,Number(button.dataset.delta)));return;} if(action==='upgrade'){completed(G.buyUpgrade(game,id));return;} if(action==='hire'){completed(G.hireStaff(game,id));return;} if(action==='fire'){openModal('Kết thúc ca làm?','<p>Nhân viên đã làm trong ngày vẫn nhận đủ lương của ngày đó.</p>',`<button class="secondary" data-action="close-modal">Giữ lại</button><button class="primary" data-action="confirm-fire" data-id="${id}">Cho nghỉ</button>`);return;} if(action==='confirm-fire'){closeModal();completed(G.fireStaff(game,id));return;} if(action==='decor'){completed(game.decoration.owned.includes(id)?G.selectDecoration(game,id):G.buyDecoration(game,id));return;}
  if(action==='review-filter'){reviewFilter=Number(id);render();return;} if(action==='reply'){const review=game.reviews.find(row=>row.id===id);openModal(`Trả lời ${review.name}`,`<textarea id="review-reply" maxlength="240" rows="4" aria-label="Nội dung trả lời">${esc(review.reply)}</textarea>`,`<button class="primary" data-action="save-reply" data-id="${esc(id)}">Lưu trả lời</button>`);return;} if(action==='save-reply'){const text=$('#review-reply').value;closeModal();completed(G.replyReview(game,id,text));return;}
  if(action==='goals'){goalsModal();return;} if(action==='claim'){const result=G.claimGoal(game,id);completed(result);goalsModal();return;} if(action==='loan'){loanModal();return;} if(action==='take-loan'){const result=G.takeLoan(game);if(result.ok)closeModal();completed(result);return;} if(action==='repay'){openModal('Trả khoản vay',`<p>Đang nợ ${money(game.debt)} · Trong ví ${money(game.money)}</p><label for="repay-amount">Số tiền trả</label><input id="repay-amount" type="number" min="1" max="${Math.max(0,Math.min(game.debt,game.money))}" value="${Math.max(0,Math.min(game.debt,game.money))}">`,'<button class="primary" data-action="confirm-repay">Trả nợ</button>');return;} if(action==='confirm-repay'){const amount=Number($('#repay-amount').value);const result=G.repayLoan(game,amount);if(result.ok)closeModal();completed(result);return;}
  if(action==='bargain'){if(!challenge)showBargaining(miniContext());return;} if(action==='secret'){if(!challenge)showSecretBroth(miniContext());return;} if(action==='wash'){if(!challenge)showWashing(miniContext());return;} if(action==='records'){recordsModal();return;} if(action==='challenge'){startChallenge();return;}
  if(!active())return;
  if(action==='incident'){const result=G.resolveIncident(game,id);if(result.ok){dialog.dataset.incident='';closeModal();}completed(result,{repaint:false});updatePlay();return;} if(action==='order'){G.selectOrder(game,id);persist();updatePlay();return;}
  if(action==='rush'){rushModal();return;} if(action==='rush-item'){const known=game.unlocked.length,result=G.buyCart(game,{[id]:5},{rush:true});persist();toast(result.message);if(game.unlocked.length!==known)play();rushModal();updatePlay();return;}
  if(action==='stockout'){const order=G.getSelectedOrder(game);if(!order){toast('Chưa có đơn đang chờ.');return;}openModal('Xin lỗi, tiệm hết món',`<p>Đơn của ${esc(order.name)}. Có thể đổi sang món trong kho hoặc hủy đơn với tác động đến đánh giá.</p>`,`<button class="secondary" data-action="close-modal">Quay lại</button><button class="secondary" data-action="resolve" data-id="${order.id}" data-kind="substitute">Gợi ý món thay thế</button><button class="primary" data-action="resolve" data-id="${order.id}" data-kind="cancel">Xin hủy đơn</button>`);return;}
  if(action==='resolve'){const result=G.resolveStockout(game,id,button.dataset.kind);closeModal();completed(result,{repaint:false});updatePlay();return;}
  if(action==='discard'){openModal('Bỏ tô đang làm?',`<p>${money(game.activeDay.bowl.cost)} nguyên liệu đã dùng sẽ thành hao phí. Không hoàn lại kho.</p>`,'<button class="secondary" data-action="close-modal">Giữ tô</button><button class="primary" data-action="confirm-discard">Bỏ tô</button>');return;}
  if(action==='finish'){const day=game.activeDay;if(game.phase==='closing'){openModal('Đóng cửa ngay?',`<p>Còn ${day.orders.length} khách. Đóng ngay sẽ tính các đơn còn lại là khách bỏ về.</p>`,'<button class="secondary" data-action="close-modal">Tiếp tục phục vụ</button><button class="primary" data-action="force-finish">Đóng ngay</button>');}else if(day.remaining>0){openModal('Đóng cửa sớm?',`<p>Còn ${clockText(day.remaining)} giờ bán. ${day.orders.length?`Không nhận khách mới; ${day.orders.length} khách đang chờ có thêm tối đa 60 giây để nhận món.`:'Không có khách đang chờ nên ngày bán kết thúc ngay.'}</p><p class="muted">Tiền thuê, điện nước và lương vẫn tính đủ. Nguyên liệu dùng trong ngày sẽ hết hạn.</p>`,'<button class="secondary" data-action="close-modal">Bán tiếp</button><button class="primary" data-action="force-finish">Đóng cửa</button>');}else handleEnd(G.finishDay(game));return;}
  if(action==='force-finish'){closeModal();handleEnd(G.finishDay(game));return;}
  let result;
  if(action==='bowl')result=G.takeBowl(game);if(action==='broth')result=G.addBroth(game,id);if(action==='topping')result=G.addTopping(game,id);if(action==='chili')result=G.addChili(game);if(action==='pot'){const index=Number(button.dataset.index);result=game.activeDay.pots[index]?G.collectPot(game,index):G.startPot(game,index);}if(action==='basket')result=G.collectBasket(game);if(action==='confirm-discard'){closeModal();result=G.discardBowl(game);}if(action==='serve')result=G.serveBowl(game,challenge?.serveRandom||Math.random);
  if(result){if(result.finished){handleEnd(result);return;}completed(result,{repaint:false,quiet:!['serve','confirm-discard'].includes(action)});updatePlay();showIncident();}
});
dialog.addEventListener('cancel',event=>{if(dialog.dataset.incident&&game?.activeDay?.pendingIncident){event.preventDefault();toast('Chọn cách xử lý để tiếp tục ca bán.');}previousTick=performance.now();});
dialog.addEventListener('close',()=>{previousTick=performance.now();});
document.addEventListener('visibilitychange',()=>{persist();previousTick=performance.now();if(!document.hidden&&screen==='play'&&active()&&!dialog.open)openModal('Tiệm đang tạm nghỉ','<p>Khách và nồi mì đã chờ bạn. Bấm tiếp tục khi sẵn sàng trở lại bếp.</p>','<button class="primary" data-action="close-modal">Tiếp tục phục vụ →</button>');});
window.addEventListener('pagehide',persist);
document.addEventListener('error',event=>{if(event.target instanceof HTMLImageElement&&!event.target.dataset.fallback){event.target.dataset.fallback='true';event.target.src='./assets/bowl.svg';}},true);
setInterval(()=>{const now=performance.now(),delta=Math.min(1,(now-previousTick)/1000);previousTick=now;if(document.hidden||dialog.open||screen!=='play'||!active())return;const result=G.tickDay(game,delta,challenge?.random||Math.random);if(result.finished){handleEnd(result);return;}paintElapsed+=delta;saveElapsed+=delta;if(result.lostOrders?.length)toast(`${result.lostOrders.length} khách đã hết kiên nhẫn.`);if(paintElapsed>=.15){paintElapsed=0;updatePlay();}if(saveElapsed>=2){saveElapsed=0;persist();}},100);
applySettings(); if(game?.legacySave)persist(); render();
